const uid = () => 'ai_fs_' + Math.random().toString(36).substring(2, 11) + Date.now().toString(36);
const now = new Date().toISOString();

function makeTask(title, extraProps = {}) {
  return {
    id: uid(),
    title,
    status: 'not-started',
    priority: extraProps.priority || 'medium',
    notes: extraProps.notes || '',
    createdAt: now,
    ...extraProps
  };
}

function makeDay(dayNum, mainTopic, objective, tasksList, practiceList, dsaTask, projectTask, revisionPrompt, extra = {}) {
  const allTasks = [];

  // Main Topic Learning Tasks
  (tasksList || []).forEach(t => {
    allTasks.push(makeTask(typeof t === 'string' ? t : t.title, { type: 'learning', topic: mainTopic }));
  });

  // Practice Tasks
  (practiceList || []).forEach(p => {
    allTasks.push(makeTask('Practice: ' + (typeof p === 'string' ? p : p.title), { type: 'practice', priority: 'high' }));
  });

  // DSA Task
  if (dsaTask) {
    allTasks.push(makeTask('DSA: ' + dsaTask, { type: 'dsa', priority: 'high' }));
  }

  // Project Task
  if (projectTask) {
    allTasks.push(makeTask('Project: ' + projectTask, { type: 'project', priority: 'high' }));
  }

  // Revision Task
  if (revisionPrompt) {
    allTasks.push(makeTask('Revision: ' + revisionPrompt, { type: 'revision', priority: 'medium' }));
  }

  return {
    id: uid(),
    dayNumber: dayNum,
    name: `Day ${dayNum} — ${mainTopic}`,
    mainTopic,
    objective,
    dsa: dsaTask,
    projectTask,
    revision: revisionPrompt,
    estimatedMinutes: 180,
    status: 'not-started',
    date: '',
    tasks: allTasks,
    ...extra
  };
}

function makeWeek(weekNum, name, objective, days = [], checkpoint = '') {
  return {
    id: uid(),
    weekNumber: weekNum,
    name: `Week ${weekNum} — ${name}`,
    objective,
    checkpoint,
    days
  };
}

function makeMonth(monthNum, phaseName, name, objective, weeks = [], monthlyProject = '', monthlyCheckpoint = '') {
  return {
    id: uid(),
    monthNumber: monthNum,
    phase: phaseName,
    name: `MONTH ${monthNum} — ${name}`,
    objective,
    monthlyProject,
    monthlyCheckpoint,
    weeks
  };
}

// Assign weekday dates starting from today
function assignDates(months) {
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  let dayOffset = 0;

  months.forEach((month) => {
    (month.weeks || []).forEach((week) => {
      (week.days || []).forEach((day) => {
        const d = new Date(start);
        d.setDate(d.getDate() + dayOffset);
        while (d.getDay() === 0 || d.getDay() === 6) {
          d.setDate(d.getDate() + 1);
          dayOffset++;
        }
        day.date = d.toISOString().split('T')[0];
        dayOffset++;
      });
    });
  });
  return months;
}

